cd /app && python3 - << 'EOF'
import sys, json, itertools
sys.path.insert(0, '/workspace/tests')
from lib import *

c = itertools.count()
def s(sid, off, h, fin=False): return F("STREAM", id=sid, offset=off, data_hex=h, fin=fin)
def r(sid, size): return F("RESET_STREAM", id=sid, final_size=size)
def C(off, h): return F("CRYPTO", offset=off, data_hex=h)
def P(): return F("PING")
def CL(app, code): return F("CLOSE", app=app, code=code)
def ACK(rng): return F("ACK", ranges=rng)
def d(p, t): return dg(t, 1200, [p])
def p(*frames, level="A", pn=None, auth=True): return pkt(level, next(c) if pn is None else pn, list(frames), auth)
def K(t,lvl,act): return key(t,lvl,act)
def oneA(events, **kw): return one([K(0,"A","install")] + events, **kw)

v = view(oneA([d(p(C(0,"aabb"), s(0,0,"61"), C(4,"cc"), r(0,0)),1)]))
print("rollback:", v["pk"], v["conn"], v["cr"], v["st"], v["rt"])
v = view(oneA([d(p(s(0,0,"61")),1), d(p(s(0,0,"6162",True), CL(True,1)),2)]))
print("err before close:", v["pk"], v["conn"], v["st"], v["rt"])
v = view(oneA([d(p(CL(True,1)),5), K(6,"H","install"), K(7,"I","discard"), {"t":9,"op":"tick"}], idle_ms=2))
print("i8:", v["keys"], v["conn"], v["pk"])
v = view(oneA([d(p(P(), level="H", pn=0),1), K(5,"A","install"), d(p(P(), pn=0),6), d(p(P(), pn=0),16), {"t":20,"op":"tick"}], idle_ms=10))
print("i7:", v["pk"], v["conn"])
# drop new packets after close
v = view(oneA([d(p(CL(True,4)),2), d(p(s(0,0,"61")),3), d(p(C(0,"aa"), level="I", pn=9),4)]))
print("after-close drops:", v["pk"], v["conn"], v["st"], v["rt"], v["cr"])
# terminate + LAYOUT
v = view(oneA([d(p(CL(True,4)),2), d([p(P(), level="A", pn=5), p(P(), level="I", pn=6)][0:2],3)]))
print("layout after close:", v["pk"])
# pending dropped at idle termination
v = view(oneA([d(p(C(0,"aa"), level="H", pn=0),1), {"t":50,"op":"tick"}], idle_ms=10))
print("idle drops:", v["pk"], v["conn"], v["cr"])
EOF
